    """ Builder interface """
from abc import ABC, abstractmethod

class Builder(ABC):
    @abstractmethod
    def buildCPU(self):
        pass

    @abstractmethod
    def buildRAM(self):
        pass

    @abstractmethod
    def buildStorage(self):
        pass

    @abstractmethod
    def getResult(self):
        pass


