4. DirectorA class that controls the building process by calling builder methods in the correct order to construct the product.
            C++

    // Director
class ComputerDirector {
public:
    void construct(Builder& builder) {
        builder.buildCPU();
        builder.buildRAM();
        builder.buildStorage();
    }
};


